<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{enterpriseApi,selectTenant,type TenantContext}from'@/api/enterprise';import{orchestrationApi as api}from'@/api/orchestration'
const tab=ref('overview'),loading=ref(true),ctx=ref<TenantContext|null>(null),overview=ref<any>({}),workflows=ref<any[]>([]),runs=ref<any[]>([]),approvals=ref<any[]>([]),tools=ref<any[]>([]),prompts=ref<any[]>([]),routes=ref<any[]>([]),datasets=ref<any[]>([]),templates=ref<any[]>([]),memories=ref<any[]>([]),selected=ref<any>(),runDetail=ref<any>(),evalResult=ref<any>()
const graph=reactive<any>({nodes:[{id:'start',type:'start',config:{}},{id:'end',type:'end',config:{}}],edges:[{source:'start',target:'end'}]}),flow=reactive({name:'',description:'',change_note:'Initial version'}),node=reactive({id:'',type:'agent',configValue:''}),edge=reactive({source:'start',target:'end',condition:'always'}),prompt=reactive({key:'',system_prompt:'',input_variables:[],status:'active'}),route=reactive({task_type:'general',primary_model:'',fallback_models:[],max_cost_cents:100,max_tokens:4000,enabled:true}),dataset=reactive({name:'',cases:'[{"name":"baseline","input":{},"forbidden_tools":[]}]',threshold:.8}),memory=reactive({namespace:'workflow',key:'',value:'{}',ttl_seconds:86400}),runForm=reactive({budget_cents:100,input:'{}'}),templateForm=reactive({key:'',name:'',category:'operations',published:true})
const can=(p:string)=>ctx.value?.permissions.includes(p),pending=computed(()=>approvals.value.filter(x=>x.status==='pending'))
async function load(){loading.value=true;try{ctx.value=await enterpriseApi.context();selectTenant(ctx.value.organization.id,ctx.value.workspaces[0]?.id);[overview.value,workflows.value,runs.value,approvals.value,tools.value,prompts.value,routes.value,datasets.value,templates.value,memories.value]=await Promise.all([api.overview(),api.workflows(),api.runs(),api.approvals(),api.tools(),api.prompts(),api.routes(),api.datasets(),api.templates(),api.memories()])}finally{loading.value=false}}
function addNode(){if(!node.id||graph.nodes.some((x:any)=>x.id===node.id))return ElMessage.warning('节点 ID 不能为空且必须唯一');const cfg:any={};if(node.type==='agent')cfg.prompt_key=node.configValue||'default';if(node.type==='tool')cfg.tool_key=node.configValue||'memory.read';if(node.type==='approval')cfg.summary=node.configValue||'人工复核';if(node.type.startsWith('memory'))cfg.key=node.configValue||node.id;graph.nodes.push({id:node.id,type:node.type,config:cfg});node.id=''}
function addEdge(){if(!graph.nodes.some((x:any)=>x.id===edge.source)||!graph.nodes.some((x:any)=>x.id===edge.target))return ElMessage.warning('请选择有效节点');graph.edges.push({...edge});edge.source=edge.target;edge.target='end'}
function removeNode(id:string){if(['start','end'].includes(id))return;graph.nodes=graph.nodes.filter((x:any)=>x.id!==id);graph.edges=graph.edges.filter((x:any)=>x.source!==id&&x.target!==id)}
async function createFlow(){await api.createWorkflow({...flow,workspace_id:ctx.value?.workspaces[0]?.id,graph});flow.name='';await load();ElMessage.success('工作流草稿已创建')}
async function openFlow(id:string){selected.value=await api.workflow(id);const active=selected.value.versions.find((x:any)=>x.id===selected.value.active_version_id)||selected.value.versions[0];Object.assign(graph,JSON.parse(JSON.stringify(active.graph)));tab.value='designer'}
async function newVersion(){await api.version(selected.value.id,{graph,change_note:'Designer update'});selected.value=await api.workflow(selected.value.id);ElMessage.success('不可变版本已创建')}
async function startRun(w:any){const r=await api.start(w.id,{budget_cents:runForm.budget_cents,input:JSON.parse(runForm.input),idempotency_key:`ui:${w.id}:${Date.now()}`});await load();await openRun(r.id)}
async function openRun(id:string){runDetail.value=await api.run(id);tab.value='trace'}
async function decide(id:string,decision:string){await api.decide(id,{decision,note:'已在 Agent 编排控制台复核风险与输入'});await load();if(runDetail.value)runDetail.value=await api.run(runDetail.value.id)}
async function savePolicy(tool:any,effect:string){await api.policy({tool_id:tool.id,workspace_id:ctx.value?.workspaces[0]?.id,effect,require_approval:true,max_calls_per_run:3,constraints:{}});tools.value=await api.tools()}
async function addPrompt(){await api.createPrompt(prompt);prompts.value=await api.prompts();prompt.key='';prompt.system_prompt=''}async function saveRoute(){await api.saveRoute({...route,workspace_id:ctx.value?.workspaces[0]?.id});routes.value=await api.routes()}
async function addDataset(){await api.createDataset({name:dataset.name,cases:JSON.parse(dataset.cases),thresholds:{minimum_score:dataset.threshold}});datasets.value=await api.datasets();dataset.name=''}async function runEval(d:any){const version=selected.value?.versions?.[0]?.id;if(!version)return ElMessage.warning('先打开一个工作流');evalResult.value=await api.evaluate(d.id,version);ElMessage[evalResult.value.passed?'success':'warning'](`评测得分 ${evalResult.value.score}`)}
async function addMemory(){await api.putMemory({...memory,workspace_id:ctx.value?.workspaces[0]?.id,value:JSON.parse(memory.value)});memories.value=await api.memories();memory.key=''}async function publishTemplate(){await api.createTemplate({...templateForm,graph});templates.value=await api.templates()}
onMounted(load)
</script>
<template><main class="orchestration"><header><div><small>AGENT ORCHESTRATION</small><h1>智能自治与 Agent 编排</h1><p>设计、评测并运行受租户策略、预算和人工审批约束的持久化工作流。</p></div><div v-if="ctx" class="tenant"><strong>{{ctx.organization.name}}</strong><span>{{ctx.membership.role_key}} · {{ctx.organization.data_region}}</span></div></header><div v-if="loading" class="state">正在加载编排运行时...</div><template v-else><nav><button v-for="x in [['overview','概览'],['workflows','工作流'],['designer','设计器'],['runs','运行'],['approvals','审批'],['tools','工具策略'],['prompts','Prompt 与模型'],['evaluations','评测'],['templates','模板市场'],['memory','记忆']]" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}<b v-if="x[0]==='approvals'&&pending.length">{{pending.length}}</b></button></nav>
<section v-if="tab==='overview'"><div class="metrics"><article><span>工作流</span><strong>{{overview.workflows}}</strong></article><article><span>运行中</span><strong>{{overview.running}}</strong></article><article><span>待审批</span><strong>{{overview.pending_approvals}}</strong></article><article><span>注册工具</span><strong>{{overview.tools}}</strong></article></div><div class="notice"><strong>自治边界已启用</strong><span>工具默认拒绝；高风险操作需双人复核；模型调用受版本、路由与成本预算限制。</span></div></section>
<section v-else-if="tab==='workflows'"><h2>工作流</h2><form v-if="can('agents.manage')" @submit.prevent="createFlow" class="form"><input v-model="flow.name" required placeholder="工作流名称"><input v-model="flow.description" placeholder="用途说明"><button>创建当前设计</button></form><div class="rows"><div v-for="x in workflows"><strong>{{x.name}}</strong><span>{{x.status}} · {{x.workspace_id?'Workspace':'组织级'}}</span><code>{{x.active_version_id?.slice(0,12)}}</code><span class="actions"><button @click="openFlow(x.id)">打开</button><button v-if="x.status==='active'&&can('agents.run')" @click="startRun(x)">运行</button></span></div></div></section>
<section v-else-if="tab==='designer'"><div class="sectionhead"><div><h2>工作流设计器</h2><p>{{selected?.name||'新工作流'}} · 节点 ID 和连线构成可审计的 DAG</p></div><button v-if="selected&&can('agents.manage')" @click="newVersion">保存新版本</button></div><div class="designer"><aside><h3>新增节点</h3><input v-model="node.id" placeholder="稳定节点 ID"><select v-model="node.type"><option v-for="x in ['agent','tool','approval','condition','memory_read','memory_write']">{{x}}</option></select><input v-model="node.configValue" placeholder="Prompt/Tool/Key"><button @click="addNode">添加节点</button><h3>新增连线</h3><select v-model="edge.source"><option v-for="x in graph.nodes" :value="x.id">{{x.id}}</option></select><select v-model="edge.target"><option v-for="x in graph.nodes" :value="x.id">{{x.id}}</option></select><select v-model="edge.condition"><option>always</option><option>true</option><option>false</option></select><button @click="addEdge">添加连线</button></aside><div class="canvas"><article v-for="x in graph.nodes" :class="x.type"><small>{{x.type}}</small><strong>{{x.id}}</strong><code>{{Object.values(x.config||{}).join(' · ')}}</code><button v-if="!['start','end'].includes(x.id)" title="删除节点" @click="removeNode(x.id)">×</button></article><div class="edges"><span v-for="x in graph.edges"><code>{{x.source}}</code> → <code>{{x.target}}</code> <i>{{x.condition}}</i></span></div></div></div></section>
<section v-else-if="tab==='runs'"><h2>持久化运行</h2><div class="runconfig"><label>单次成本上限（分）<input v-model.number="runForm.budget_cents" type="number" min="0"></label><label>运行输入<textarea v-model="runForm.input"></textarea></label></div><div class="rows"><div v-for="x in runs"><strong>{{x.status}}</strong><span>{{x.workflow_id.slice(0,12)}} · {{x.current_node_id||'terminal'}}</span><span>¥{{(x.spent_cents/100).toFixed(2)}} / ¥{{(x.budget_cents/100).toFixed(2)}}</span><span class="actions"><button @click="openRun(x.id)">执行链路</button><button v-if="x.status==='failed'" @click="api.replay(x.id).then(load)">重放</button></span></div></div></section>
<section v-else-if="tab==='trace'"><div class="sectionhead"><div><h2>执行链路</h2><p>{{runDetail?.id}} · {{runDetail?.status}}</p></div><span class="actions"><button v-if="runDetail?.status==='queued'" @click="api.advance(runDetail.id).then(()=>openRun(runDetail.id))">推进一步</button><button v-if="!['completed','failed','cancelled'].includes(runDetail?.status)" class="danger" @click="api.cancel(runDetail.id).then(()=>openRun(runDetail.id))">取消</button></span></div><div class="trace"><article v-for="x in runDetail?.steps"><span>{{x.attempt}}</span><div><strong>{{x.node_id}} · {{x.node_type}}</strong><small>{{x.status}}</small><pre v-if="x.output&&Object.keys(x.output).length">{{JSON.stringify(x.output,null,2)}}</pre><p v-if="x.error">{{x.error}}</p></div></article></div><h3>审计日志</h3><div class="audit"><p v-for="x in runDetail?.audit"><time>{{new Date(x.created_at).toLocaleString()}}</time><strong>{{x.action}}</strong><code>{{JSON.stringify(x.details)}}</code></p></div></section>
<section v-else-if="tab==='approvals'"><h2>人工审批</h2><div class="rows"><div v-for="x in approvals"><strong>{{x.risk_summary}}</strong><code>{{x.requested_action.tool||'workflow checkpoint'}}</code><span>{{x.status}}</span><span v-if="x.status==='pending'&&can('agents.approve')" class="actions"><button @click="decide(x.id,'approved')">批准</button><button class="danger" @click="decide(x.id,'rejected')">拒绝</button></span></div></div></section>
<section v-else-if="tab==='tools'"><h2>租户工具注册表与调用策略</h2><div class="rows"><div v-for="x in tools"><strong>{{x.key}}<small>{{x.risk_level}}</small></strong><span>{{x.connector_key||'内部工具'}} · {{x.action}}</span><span>{{x.policy?.effect||'默认拒绝'}} · {{x.policy?.require_approval?'需审批':'自动'}}</span><span v-if="can('agents.manage')" class="actions"><button @click="savePolicy(x,'allow')">允许</button><button class="danger" @click="savePolicy(x,'deny')">拒绝</button></span></div></div></section>
<section v-else-if="tab==='prompts'"><h2>Prompt 版本与模型路由</h2><form v-if="can('agents.manage')" @submit.prevent="addPrompt" class="form prompt"><input v-model="prompt.key" required placeholder="Prompt key"><textarea v-model="prompt.system_prompt" required placeholder="系统 Prompt"></textarea><button>发布 Prompt 版本</button></form><div class="rows compact"><div v-for="x in prompts"><strong>{{x.key}}:v{{x.version}}</strong><span>{{x.status}}</span></div></div><form v-if="can('agents.manage')" @submit.prevent="saveRoute" class="form"><input v-model="route.task_type" required placeholder="任务类型"><input v-model="route.primary_model" required placeholder="真实模型 ID"><input v-model.number="route.max_cost_cents" type="number" min="0" title="每步成本上限"><button>保存路由</button></form><div class="rows compact"><div v-for="x in routes"><strong>{{x.task_type}}</strong><span>{{x.primary_model}} · {{x.max_tokens}} tokens · {{x.max_cost_cents}} 分</span></div></div></section>
<section v-else-if="tab==='evaluations'"><h2>评测数据集与发布门禁</h2><form v-if="can('agents.manage')" @submit.prevent="addDataset" class="form prompt"><input v-model="dataset.name" required placeholder="数据集名称"><textarea v-model="dataset.cases" required></textarea><button>创建数据集</button></form><div v-if="evalResult" class="notice"><strong>{{evalResult.passed?'评测通过':'评测未通过'}}</strong><span>Score {{evalResult.score}} · 未通过的版本不能激活。</span></div><div class="rows"><div v-for="x in datasets"><strong>{{x.name}}</strong><span>{{x.case_count}} cases · threshold {{x.thresholds.minimum_score}}</span><span></span><button @click="runEval(x)">运行回归</button></div></div></section>
<section v-else-if="tab==='templates'"><h2>工作流模板市场</h2><form v-if="can('agents.manage')" @submit.prevent="publishTemplate" class="form"><input v-model="templateForm.key" required placeholder="模板 key"><input v-model="templateForm.name" required placeholder="模板名称"><button>发布当前设计</button></form><div class="catalog"><article v-for="x in templates"><strong>{{x.name}}</strong><span>{{x.category}} · v{{x.version}}</span><p>{{x.graph.nodes.length}} nodes</p><button v-if="can('agents.manage')" @click="api.install(x.id).then(load)">安装为草稿</button></article></div></section>
<section v-else><h2>Agent 记忆生命周期</h2><form @submit.prevent="addMemory" class="form"><input v-model="memory.namespace" required placeholder="namespace"><input v-model="memory.key" required placeholder="key"><input v-model="memory.value" required placeholder='{"value":"..."}'><button>写入记忆</button></form><div class="rows"><div v-for="x in memories"><strong>{{x.namespace}} / {{x.key}}</strong><code>{{JSON.stringify(x.value)}}</code><span>{{x.expires_at?new Date(x.expires_at).toLocaleString():'长期'}}</span><button class="danger" @click="api.deleteMemory(x.id).then(load)">删除</button></div></div></section></template></main></template>
<style scoped>.orchestration{padding:30px;min-height:100vh;background:#f4f6f5;color:#18221e}.orchestration>header{display:flex;justify-content:space-between;align-items:end;gap:20px}.orchestration small{color:#197268;font-weight:800}.orchestration h1{margin:5px 0;font-size:32px}.orchestration p{color:#64706b}.tenant{text-align:right}.tenant strong,.tenant span{display:block}nav{display:flex;overflow:auto;border-bottom:1px solid #cad5d0;margin:24px 0}nav button{white-space:nowrap;border:0;background:none;padding:12px 14px}nav button.active{color:#116d62;border-bottom:2px solid #116d62}nav b{margin-left:5px;padding:1px 5px;border-radius:10px;background:#a13b43;color:white}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #d6dfdb;background:white}.metrics article{padding:18px;border-right:1px solid #e0e6e3}.metrics span,.metrics strong{display:block}.metrics strong{font-size:25px}.notice{margin:20px 0;border-left:3px solid #197268;background:#e8f2ee;padding:15px}.notice span{display:block}.form{display:grid;grid-template-columns:1.2fr 2fr auto;gap:10px;margin:15px 0;max-width:1000px}.form.prompt{grid-template-columns:1fr 3fr auto}.runconfig{display:flex;gap:12px}.runconfig label{display:grid;gap:5px}.runconfig textarea{width:400px}.sectionhead{display:flex;justify-content:space-between;align-items:center}.rows{border-top:1px solid #d3dcd8}.rows>div{display:grid;grid-template-columns:minmax(140px,1fr) minmax(200px,2fr) minmax(160px,1.5fr) auto;gap:12px;align-items:center;padding:13px 4px;border-bottom:1px solid #d3dcd8}.rows.compact>div{grid-template-columns:1fr 2fr}.rows strong small{display:block}.actions{display:flex;gap:6px}input,select,textarea{min-width:0;padding:10px;border:1px solid #bdc9c4;border-radius:4px;background:white}button{border:0;border-radius:4px;background:#dfe8e4;color:#173c35;padding:9px 13px;cursor:pointer}form button,.actions button:first-child,.sectionhead>button{background:#176f67;color:white}.danger{background:#a13b43!important;color:white}.designer{display:grid;grid-template-columns:220px 1fr;min-height:520px;border:1px solid #ccd7d2}.designer>aside{padding:15px;background:#edf2f0;display:flex;flex-direction:column;gap:8px}.canvas{padding:24px;display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));align-content:start;gap:14px;background-image:linear-gradient(#e2e8e5 1px,transparent 1px),linear-gradient(90deg,#e2e8e5 1px,transparent 1px);background-size:20px 20px}.canvas article{position:relative;display:grid;min-height:76px;padding:12px;border:1px solid #b9c8c2;border-left:4px solid #197268;background:white}.canvas article.approval,.canvas article.tool{border-left-color:#b77b16}.canvas article.end{border-left-color:#8a4c55}.canvas article button{position:absolute;right:4px;top:4px;padding:2px 6px}.edges{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:7px}.edges span{padding:6px;background:#edf2f0}.edges i{color:#8b691e}.trace{max-width:900px}.trace article{display:grid;grid-template-columns:35px 1fr;gap:12px}.trace article>span{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#176f67;color:white}.trace article>div{border-left:1px solid #bac8c2;padding:0 0 20px 18px}.trace small{display:block}.trace pre{white-space:pre-wrap;background:#17241f;color:#e5eee9;padding:10px}.audit p{display:grid;grid-template-columns:170px 170px 1fr;gap:10px}.catalog{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#d4ded9;border:1px solid #d4ded9}.catalog article{background:white;padding:15px}.catalog strong,.catalog span{display:block}.state{padding:60px;text-align:center}@media(max-width:760px){.orchestration{padding:76px 12px 24px}.tenant{display:none}.metrics{grid-template-columns:1fr 1fr}.form,.form.prompt{grid-template-columns:1fr}.rows{overflow:auto}.rows>div{min-width:700px}.designer{grid-template-columns:1fr}.canvas{grid-template-columns:1fr 1fr}.catalog{grid-template-columns:1fr 1fr}.runconfig{display:grid}.runconfig textarea{width:100%}.audit p{grid-template-columns:1fr}.sectionhead{align-items:start;gap:10px}}</style>
